[
  {
    "statement": "Chemical methods using herbicides show variable effectiveness against Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "Applying glyphosate reduced Crassula helmsii in seven studies.",
    "citations": [
      "1279"
    ]
  },
  {
    "statement": "One study showed a 98% reduction in Crassula helmsii when glyphosate was combined with diquat.",
    "citations": [
      "1279"
    ]
  },
  {
    "statement": "In three out of four studies, applying diquat or diquat alginate reduced cover or eradicated submerged Crassula helmsii.",
    "citations": [
      "1279"
    ]
  },
  {
    "statement": "One small trial found that applying diquat or diquat alginate had no effect on Crassula helmsii.",
    "citations": [
      "1279"
    ]
  },
  {
    "statement": "Other herbicides, such as dichlobenil and terbutryne, showed partial reduction in Crassula helmsii biomass in container trials.",
    "citations": [
      "1279"
    ]
  },
  {
    "statement": "Hydrogen peroxide did not control Crassula helmsii in controlled tank trials.",
    "citations": [
      "1281"
    ]
  },
  {
    "statement": "Physical methods show strong effectiveness for controlling Crassula helmsii in specific applications.",
    "citations": []
  },
  {
    "statement": "Lightproof barriers using black sheeting or carpet strips eradicated or severely reduced Crassula helmsii cover in five before-and-after studies.",
    "citations": [
      "1294"
    ]
  },
  {
    "statement": "Progressive recolonization of Crassula helmsii occurred at two sites where eradication had initially been reported.",
    "citations": [
      "1294"
    ]
  },
  {
    "statement": "Salt water treatment eradicated Crassula helmsii in two replicated controlled container trials.",
    "citations": [
      "1288"
    ]
  },
  {
    "statement": "Salt water treatment eradicated Crassula helmsii in two before-and-after field trials.",
    "citations": [
      "1288"
    ]
  },
  {
    "statement": "Combined approaches show enhanced effectiveness against Crassula helmsii.",
    "citations": []
  },
  {
    "statement": "Covering Crassula helmsii with carpet followed by glyphosate treatment killed 80% of the plant in one study.",
    "citations": [
      "1313"
    ]
  },
  {
    "statement": "Covering Crassula helmsii with carpet before treating the plant with glyphosate resulted in an 80% reduction in another study.",
    "citations": [
      "1279"
    ]
  }
]

[
  {
    "statement": "Several methods have been tested for controlling American bullfrog populations in small ponds.",
    "citations": []
  },
  {
    "statement": "Direct removal of juveniles using double fyke nets was found to be effective in catching bullfrog tadpoles in small shallow ponds.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "A study in France found a significant reduction in the number of recorded adults and juveniles following the removal of juveniles by trapping when carried out as part of a combination treatment.",
    "citations": [
      "1046"
    ]
  },
  {
    "statement": "One study found that bullfrog adults can be captured overnight in a single trap floating on the water surface.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "The catchability of adult bullfrogs in small shallow ponds using one double fyke net for 24 hours was found to be very low.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Bullfrog populations rapidly rebounded following intensive removal of adults.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "A study in France found a significant reduction in the number of recorded adults and juveniles following the shooting of metamorphosed individuals before reproduction when carried out as part of a combination treatment.",
    "citations": [
      "1045"
    ]
  },
  {
    "statement": "Biological control using native predators showed promise for controlling American bullfrog populations.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "The introduction of northern pike led to a strong decline in bullfrog tadpole numbers.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "Chemical methods have been tested for controlling American bullfrog populations.",
    "citations": [
      "1048"
    ]
  },
  {
    "statement": "Caffeine (10% solution), chloroxylenol (5% solution), and a combined treatment of Permethrin (4.6% solution) and Rotenone (1% solution) were found to kill American bullfrogs.",
    "citations": [
      "1048"
    ]
  },
  {
    "statement": "Removing bullfrogs can benefit native species.",
    "citations": [
      "825"
    ]
  },
  {
    "statement": "The removal of bullfrogs significantly increased California red-legged frog populations.",
    "citations": [
      "825"
    ]
  },
  {
    "statement": "The removal of bullfrogs increased the leopard frog range.",
    "citations": [
      "825"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of draining ponds to control bullfrog populations.",
    "citations": [
      "1042",
      "1043"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of altering pond water duration to control bullfrog populations.",
    "citations": [
      "1042",
      "1043"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of pond destruction to control bullfrog populations.",
    "citations": [
      "1042",
      "1043"
    ]
  }
]

[
  {
    "statement": "Based on the available evidence, herbivore biological control shows mixed outcomes for invasive aquatic plants.",
    "citations": []
  },
  {
    "statement": "For parrot's feather, grass carp produced variable results across different studies.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "One laboratory study in Portugal found that grass carp did not reduce biomass or cover of parrot's feather.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "Two field studies in Argentina and the USA found that stocking with grass carp reduced the biomass or abundance of parrot's feather.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "A field study in South Africa reported reduced growth of parrot's feather following the release of a South American leaf-feeding Lysathia beetle.",
    "citations": [
      "1599"
    ]
  },
  {
    "statement": "For water primrose, co-evolved host-specific herbivores showed promising results.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "A field study in China found that a flea beetle caused heavy feeding destruction when added to field cages containing prostrate water primrose seedlings.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "The flea beetle studied in China was specific to the prostrate water primrose and Indian toothcup.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "A field study in the USA found that introduction of flea beetles to a pond significantly reduced the abundance of large-flower primrose-willow.",
    "citations": [
      "1135"
    ]
  },
  {
    "statement": "No evidence was found for biological control of floating pennywort using native herbivores.",
    "citations": [
      "1124"
    ]
  },
  {
    "statement": "No evidence was found for biological control of water primrose using native herbivores.",
    "citations": [
      "1136"
    ]
  }
]

[
  {
    "statement": "Based on systematic review evidence, there is very limited scientific evidence for effective control methods for Ponto-Caspian gobies in waterways.",
    "citations": []
  },
  {
    "statement": "Electrical barriers are a control method for Ponto-Caspian gobies with documented evidence.",
    "citations": [
      "1074"
    ]
  },
  {
    "statement": "Salinity manipulation is a control method for Ponto-Caspian gobies with documented evidence.",
    "citations": [
      "1072"
    ]
  },
  {
    "statement": "A controlled, replicated field study in the USA found that electrical barriers prevented movement of round gobies across the barriers.",
    "citations": [
      "1074"
    ]
  },
  {
    "statement": "Increasing electrical pulse duration and voltage increases the effectiveness of electrical barriers.",
    "citations": [
      "1074"
    ]
  },
  {
    "statement": "A replicated, controlled laboratory study in Canada found 100% mortality of round gobies within 48 hours of exposure to water of 30% salinity.",
    "citations": [
      "1072"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for habitat manipulation as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1064"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for using carbon dioxide concentrations as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1070"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for biological control using native predators as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1061"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for netting as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1066"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for pH alteration as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1073"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for public education as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1075"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for UV radiation as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1071"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for trapping using visual, sound and pheromonal lures as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1069"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for biocide application as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1063"
    ]
  },
  {
    "statement": "No evidence was captured during systematic searches for draining invaded waterbodies as a potential control method for Ponto-Caspian gobies.",
    "citations": [
      "1065"
    ]
  }
]

[
  {
    "statement": "Several methods exist for controlling invasive Procambarus crayfish populations.",
    "citations": []
  },
  {
    "statement": "Physical barriers have been shown to be effective in controlling invasive Procambarus crayfish populations.",
    "citations": [
      "1037"
    ]
  },
  {
    "statement": "Concrete dams across streams, specifically designed with features to prevent red swamp crayfish from crawling over the dams, have proven effective at containing the spread of populations upstream.",
    "citations": [
      "1037"
    ]
  },
  {
    "statement": "Chemical control using natural pyrethrum Pyblast at a concentration of 0.05 mg/l was found to be effective at killing red swamp crayfish.",
    "citations": [
      "1036"
    ]
  },
  {
    "statement": "The application of natural pyrethrum Pyblast to drained crayfish burrows was not effective at killing red swamp crayfish.",
    "citations": [
      "1036"
    ]
  },
  {
    "statement": "Trapping and removal methods for red swamp crayfish have been tested.",
    "citations": [
      "1029"
    ]
  },
  {
    "statement": "Food-baited traps using tinned meat trapped the most red swamp crayfish compared to traps using male and female pheromones or no bait.",
    "citations": [
      "1029"
    ]
  },
  {
    "statement": "Biological control through encouraging predators has shown promise in controlling red swamp crayfish.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Eels can reduce red swamp crayfish population size.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Pike predate on red swamp crayfish.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "Combining trapping with predator encouragement was found to significantly reduce red swamp crayfish populations in ponds.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "Combining trapping with predator encouragement was more effective at reducing red swamp crayfish populations than predation alone.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "Draining waterways is a potential method for crayfish control but currently has no captured evidence of its effectiveness.",
    "citations": [
      "1034"
    ]
  },
  {
    "statement": "Relocating vulnerable native crayfish species is a potential management option but currently has no captured evidence of its effectiveness.",
    "citations": [
      "1038"
    ]
  },
  {
    "statement": "The general removal or control of non-native crayfish is an option that currently has no captured evidence of its effectiveness.",
    "citations": [
      "797"
    ]
  }
]

[
  {
    "statement": "Several alternative methods have been studied for managing invasive Asian clam populations in industrial water systems.",
    "citations": []
  },
  {
    "statement": "Temperature control shows promise for managing Asian clam populations, as temperatures of 36°C or higher killed Asian clams within or after four days in controlled laboratory studies.",
    "citations": [
      "1116"
    ]
  },
  {
    "statement": "Mechanical removal methods have proven effective for managing Asian clam populations.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "Suction dredging reduced Asian clam densities by 96% over two weeks with the reductions persisting for a year.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "Three types of dredges were equally effective at removing Asian clams, resulting in biomass reductions ranging from 74% to >95% and density reductions ranging from 65% to 95%.",
    "citations": [
      "1120"
    ]
  },
  {
    "statement": "Equipment cleaning and maintenance approaches have shown effectiveness in managing Asian clam populations.",
    "citations": [
      "1119"
    ]
  },
  {
    "statement": "Mechanical removal and regular cleaning of industrial pipes were found to permanently remove or reduce numbers of Asian clams in Portuguese industrial systems.",
    "citations": [
      "1119"
    ]
  },
  {
    "statement": "The addition of sand filters was found to reduce numbers of Asian clams in Portuguese industrial systems.",
    "citations": [
      "1119"
    ]
  },
  {
    "statement": "Salinity modification represents a viable option for managing Asian clam populations.",
    "citations": [
      "1115"
    ]
  },
  {
    "statement": "High salinities of 18-34 parts per thousand caused 100% mortality in Asian clams during controlled laboratory studies.",
    "citations": [
      "1115"
    ]
  },
  {
    "statement": "Reducing oxygen levels was found to be an ineffective method for managing Asian clam populations.",
    "citations": [
      "1113"
    ]
  },
  {
    "statement": "Asian clams demonstrated resistance to extremely low oxygen levels regardless of water temperature or exposure duration.",
    "citations": [
      "1113"
    ]
  }
]

[
  {
    "statement": "Several factors influence the success of physical removal for invasive plants that can regenerate from fragments, such as skunk cabbage and water primrose.",
    "citations": []
  },
  {
    "statement": "Annual physical removal of recently established skunk cabbage plants over five years successfully removed the entire stock.",
    "citations": [
      "1101"
    ]
  },
  {
    "statement": "Manual removal was effective for small outbreaks of small-growing skunk cabbage plants.",
    "citations": [
      "1101"
    ]
  },
  {
    "statement": "For larger, more established populations of skunk cabbage, a large number of plants still needed to be removed each year after four years of twice-yearly full removal.",
    "citations": [
      "1101"
    ]
  },
  {
    "statement": "For water primrose, hand-pulling from pond margins successfully eradicated a smaller population.",
    "citations": [
      "1138"
    ]
  },
  {
    "statement": "Hand pulling and raking water primrose in other locations failed to reduce the plant's abundance.",
    "citations": [
      "1138"
    ]
  },
  {
    "statement": "The success of physical removal is limited when a plant's growth rate exceeds the removal rate.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "The rate of growth for floating pennywort exceeded the rate of removal following a two-week removal program.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "Enhanced success was achieved when physical removal was combined with other methods.",
    "citations": [
      "1140"
    ]
  },
  {
    "statement": "Combining glyphosate and surface active agent application with mechanical removal achieved a 75% kill rate for water primrose.",
    "citations": [
      "1140"
    ]
  },
  {
    "statement": "A combination of herbicide application, physical removal, and promotion of native plants with mulching reduced Peruvian primrose-willow coverage by 85-90%.",
    "citations": [
      "1140"
    ]
  },
  {
    "statement": "Long-term, repeated removal efforts are necessary for invasive plants that regenerate from fragments.",
    "citations": [
      "1126",
      "1101"
    ]
  },
  {
    "statement": "Monthly hand picking combined with mechanical removal was required for floating pennywort.",
    "citations": [
      "1126"
    ]
  },
  {
    "statement": "Twice-yearly removal programs for skunk cabbage spanning multiple years were necessary.",
    "citations": [
      "1101"
    ]
  }
]

[
  {
    "statement": "Dewatering (drying out) a habitat is one of the most effective actions for controlling invasive Ponto-Caspian gammarids.",
    "citations": [
      "1094"
    ]
  },
  {
    "statement": "Dewatering a habitat killed three species of invasive freshwater shrimp.",
    "citations": [
      "1094"
    ]
  },
  {
    "statement": "One species of invasive freshwater shrimp required water content levels of 4% and below before the shrimp was killed.",
    "citations": [
      "1094"
    ]
  },
  {
    "statement": "Certain chemical treatments, including iodine solution, acetic acid, Virkon S, and sodium hypochlorite, killed invasive killer shrimp in laboratory conditions.",
    "citations": [
      "1095"
    ]
  },
  {
    "statement": "The chemical treatments of iodine solution, acetic acid, Virkon S, and sodium hypochlorite were considered impractical for field application.",
    "citations": [
      "1095"
    ]
  },
  {
    "statement": "Changing salinity levels can be an effective action for controlling invasive Ponto-Caspian gammarids.",
    "citations": [
      "1091"
    ]
  },
  {
    "statement": "One study found that increasing salinity killed the majority of invasive shrimp within five hours.",
    "citations": [
      "1091"
    ]
  },
  {
    "statement": "Exposure to parasites is an effective action for controlling invasive Ponto-Caspian gammarids.",
    "citations": [
      "1089"
    ]
  },
  {
    "statement": "An introduced parasitic mould reduced populations of an invasive shrimp.",
    "citations": [
      "1089"
    ]
  },
  {
    "statement": "Changing water pH was a least effective action as it did not kill invasive killer shrimp.",
    "citations": [
      "1093"
    ]
  },
  {
    "statement": "Several chemical treatments, including methanol, citric acid, urea, hydrogen peroxide, and sucrose, did not kill invasive killer shrimp when added to freshwater.",
    "citations": [
      "1095"
    ]
  },
  {
    "statement": "Changing salinity was found to be a least effective action in one study, where increased salinity did not kill invasive killer shrimp.",
    "citations": [
      "1091"
    ]
  },
  {
    "statement": "No evidence was available for several actions, including biological control using predatory fish, exchanging ballast water, cleaning equipment, and exposure to disease-causing organisms.",
    "citations": [
      "1087",
      "1097",
      "1096",
      "1090"
    ]
  },
  {
    "statement": "Controlling the movement of gammarids showed limited effectiveness.",
    "citations": [
      "1088"
    ]
  },
  {
    "statement": "The movements of gammarids slowed down or stopped when the gammarids were exposed to predatory fish chemicals.",
    "citations": [
      "1088"
    ]
  },
  {
    "statement": "Carbonating water stunned invasive killer shrimp.",
    "citations": [
      "1088"
    ]
  }
]

[
  {
    "statement": "2,4-D appears to be more effective than diquat and glyphosate for controlling parrot's feather.",
    "citations": []
  },
  {
    "statement": "One replicated, controlled laboratory study in Brazil found that 2,4-D led to a greater reduction in growth of parrot's feather than the herbicides diquat, glyphosate or imazapyr.",
    "citations": [
      "1606"
    ]
  },
  {
    "statement": "Three laboratory studies in the USA and Brazil found that 2,4-D reduced the growth of parrot's feather.",
    "citations": [
      "1606"
    ]
  },
  {
    "statement": "One replicated, randomized, controlled field study in Portugal found that 2,4-D amine reduced the biomass of parrot's feather.",
    "citations": [
      "1606"
    ]
  },
  {
    "statement": "Two laboratory studies in the USA found that diquat reduced the growth of parrot's feather.",
    "citations": [
      "1680"
    ]
  },
  {
    "statement": "One replicated, randomized, controlled field study in Portugal found that growth of parrot's feather was not reduced after the application of diquat.",
    "citations": [
      "1680"
    ]
  },
  {
    "statement": "One replicated, randomized, controlled field study in Portugal reported reduced parrot's feather biomass after treatment with glyphosate.",
    "citations": [
      "1699"
    ]
  },
  {
    "statement": "One replicated, controlled, laboratory study in the USA reported reduced parrot's feather biomass after treatment with glyphosate.",
    "citations": [
      "1699"
    ]
  }
]

[
  {
    "statement": "A replicated, controlled study conducted in Belgium found the introduction of the northern pike led to a strong decline in American bullfrog tadpole numbers.",
    "citations": [
      "1039"
    ]
  },
  {
    "statement": "Two replicated, controlled studies in Italy found that eels fed on the red swamp crayfish and reduced the crayfish's population size.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "A replicated, controlled study from France in 2001 found that pike predated red swamp crayfish.",
    "citations": [
      "1030"
    ]
  },
  {
    "statement": "A before-and-after study in Switzerland found that introducing predators combined with trapping significantly reduced red swamp crayfish populations in a pond.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "A replicated, controlled study from Italy demonstrated that trapping and predation in combination was more effective at reducing red swamp crayfish populations than predation alone.",
    "citations": [
      "1031"
    ]
  },
  {
    "statement": "The studies documenting the effects of predator introduction on invasive species were conducted in European freshwater systems rather than in North American systems.",
    "citations": []
  },
  {
    "statement": "The studies were conducted in European countries including Belgium, Italy, France, and Switzerland.",
    "citations": []
  }
]

[
  {
    "statement": "Six management actions are available for red-eared terrapins.",
    "citations": []
  },
  {
    "statement": "Direct removal of adult red-eared terrapins using traps showed mixed effectiveness.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "A study in Spain found that Aranzadi turtle traps were effective in trapping red-eared terrapins from a river but did not eradicate the population.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "A study in the British Virgin Islands found that using sein nets to trap adult and juvenile red-eared terrapins was not successful in eradicating the population.",
    "citations": [
      "1055"
    ]
  },
  {
    "statement": "The application of a biocide to manage red-eared terrapins showed limited effectiveness.",
    "citations": [
      "1059"
    ]
  },
  {
    "statement": "One laboratory study in the USA found that glyphosate application to red-eared terrapin eggs reduced hatching success to 73%.",
    "citations": [
      "1059"
    ]
  },
  {
    "statement": "The reduction in red-eared terrapin egg hatching success occurred only at the highest experimental concentration of glyphosate and a surface active agent.",
    "citations": [
      "1059"
    ]
  },
  {
    "statement": "No evidence was captured on the effectiveness of biological control using native predators in controlling red-eared terrapin populations.",
    "citations": [
      "1056"
    ]
  },
  {
    "statement": "No evidence was captured on the effectiveness of draining invaded waterbodies in controlling red-eared terrapin populations.",
    "citations": [
      "1057"
    ]
  },
  {
    "statement": "No evidence was captured on the effectiveness of search and removal using sniffer dogs in controlling red-eared terrapin populations.",
    "citations": [
      "1058"
    ]
  },
  {
    "statement": "No evidence was captured on the effectiveness of public education in controlling red-eared terrapin populations.",
    "citations": [
      "1060"
    ]
  }
]

[
  {
    "statement": "Biocides show effectiveness for controlling both Procambarus crayfish and black bullheads in freshwater environments.",
    "citations": []
  },
  {
    "statement": "A study in the UK reported that use of a piscicide containing rotenone achieved eradication of black bullhead.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "A study in the USA found that rotenone successfully eradicated black bullhead.",
    "citations": [
      "1050"
    ]
  },
  {
    "statement": "In a USA study, one of two ponds required two separate doses of rotenone to eradicate black bullhead.",
    "citations": [
      "1050"
    ]
  },
